1	import {
2	  ChangeDetectionStrategy,
3	  Component,
4	  computed,
5	  effect,
6	  inject,
7	  signal,
8	} from '@angular/core';
9	import { Title } from '@angular/platform-browser';
10	import { ActivatedRoute, RouterOutlet } from '@angular/router';
11	import { CountryContext } from '../../core/country/country-context';
12	import { StatusMessage } from '../../shared/status-message';
13	import { CountryNotAvailable } from '../country-selection/country-not-available';
14	import { StepIndicator } from './step-indicator';
15	import { WizardScreen, isWizardScreen, screenHeading, stepOf } from './wizard-screens';
16	
17	/**
18	 * Component of `/:country` (ADR-0001). Resolves the country and shows "cargando", "error de carga"
19	 * + "reintentar", "país no disponible" with the published countries, or the wizard: the step
20	 * indicator (REQ-01.31) and the step routed below. Provides the `CountryContext` of its steps.
21	 */
22	@Component({
23	  selector: 'app-country-shell',
24	  changeDetection: ChangeDetectionStrategy.OnPush,
25	  providers: [CountryContext],
26	  imports: [RouterOutlet, StatusMessage, StepIndicator, CountryNotAvailable],
27	  template: `
28	    <div class="shell">
29	      @switch (context.state()) {
30	        @case ('loading') {
31	          <app-status-message kind="loading" />
32	        }
33	        @case ('error') {
34	          <app-status-message kind="error" (retry)="context.reload()" />
35	        }
36	        @case ('notAvailable') {
37	          <app-country-not-available />
38	        }
39	        @case ('ready') {
40	          @let wizard = wizardTexts();
41	          @if (wizard) {
42	            @if (currentStep(); as step) {
43	              <app-step-indicator
44	                [label]="wizard.stepIndicatorLabel"
45	                [steps]="[wizard.step1Label, wizard.step2Label, wizard.step3Label]"
46	                [current]="step"
47	              />
48	            }
49	            <router-outlet (activate)="onActivate()" />
50	          } @else {
51	            <app-status-message kind="message" [message]="genericErrorMessage()" />
52	          }
53	        }
54	      }
55	    </div>
56	  `,
57	  styles: `
58	    /* Central container; no top padding so the hero band touches the brand band (D12). */
59	    .shell {
60	      max-width: var(--container-max);
61	      margin: 0 auto;
62	      padding: 0 var(--gutter);
63	    }
64	  `,
65	})
66	export class CountryShell {
67	  protected readonly context = inject(CountryContext);
68	  private readonly route = inject(ActivatedRoute);
69	  private readonly title = inject(Title);
70	
71	  private readonly currentScreen = signal<WizardScreen | null>(null);
72	
73	  protected readonly currentStep = computed(() => {
74	    const screen = this.currentScreen();
75	    return screen === null ? null : stepOf(screen);
76	  });
77	
78	  /** Wizard texts, or `null` if one is missing (configuration error, G2-2). */
79	  protected readonly wizardTexts = computed(() => {
80	    const wizard = this.context.config()?.texts.wizard;
81	    return wizard?.status === 'ok' ? wizard.texts : null;
82	  });
83	
84	  protected readonly genericErrorMessage = computed(
85	    () => this.context.config()?.genericErrorMessage ?? '',
86	  );
87	
88	  constructor() {
89	    // document.title follows the heading of the current screen (ADR-0004), always a Strapi text.
90	    effect(() => {
91	      const config = this.context.config();
92	      const screen = this.currentScreen();
93	      if (!config) {
94	        return;
95	      }
96	      if (config.texts.wizard.status !== 'ok') {
97	        this.title.setTitle(config.genericErrorMessage);
98	      } else if (screen) {
99	        this.title.setTitle(screenHeading(config, screen).text);
100	      }
101	    });
102	  }
103	
104	  protected onActivate(): void {
105	    const screen: unknown = this.route.firstChild?.snapshot.data['screen'];
106	    this.currentScreen.set(isWizardScreen(screen) ? screen : null);
107	  }
108	}
