45	      warnings.push(`[cms] country skipped: invalid code or name (index=${index})`);
46	      return;
47	    }
48	    if (seen.has(code)) {
49	      warnings.push(`[cms] country skipped: duplicated code (code=${code})`);
50	      return;
51	    }
52	    seen.add(code);
53	    countries.push({ code, name });
54	  });
55	  return { countries, warnings };
