90	/** C3 part of the configuration: country data and texts, before combining with C4. */
91	export type CountryDataMapping =
92	  | { readonly status: 'notAvailable' }
93	  | {
94	      readonly status: 'ready';
95	      readonly country: Country;
96	      readonly genericErrorMessage: string;
97	      readonly texts: UiTexts;
98	    };
99	
100	/**
101	 * C3 → country data and texts (api-contracts C3).
102	 *
103	 * - 0 items → `notAvailable` ("país no disponible").
104	 * - More than 1 item, invalid market data, or no `genericErrorMessage` → throws a contract error,
105	 *   shown as "error de carga" + "reintentar" (REQ-01.4, REQ-01.13).
106	 * - A missing screen text only marks that screen (or summary section) as `configError`.
107	 */
108	export function mapCountryConfig(
109	  data: readonly unknown[],
110	  requestedCode: string,
111	): CountryDataMapping {
112	  if (data.length === 0) {
113	    return { status: 'notAvailable' };
114	  }
115	  if (data.length > 1) {
116	    throw contractError(`more than one country with code ${requestedCode}`);
117	  }
118	  const dto = asDto<keyof CountryConfigDto & string>(data[0]);
119	  if (!dto) {
120	    throw contractError('country is not an object');
121	  }
122	  if (dto.code !== requestedCode) {
123	    throw contractError(`country code does not match ${requestedCode}`);
124	  }
125	  const name = trimmedString(dto.name);
126	  const intlLocale = trimmedString(dto.intlLocale);
127	  const currency = trimmedString(dto.currency);
128	  if (name === null || intlLocale === null || currency === null) {
129	    throw contractError(`missing market data for ${requestedCode}`);
130	  }
131	  if (!isSupportedByIntl(intlLocale, currency)) {
132	    throw contractError(`intlLocale or currency not accepted by Intl for ${requestedCode}`);
133	  }
134	  const minimumAge = dto.minimumAge;
135	  if (typeof minimumAge !== 'number' || !Number.isInteger(minimumAge) || minimumAge < 0) {
136	    throw contractError(`invalid minimumAge for ${requestedCode}`);
137	  }
138	
139	  const wizardRaw = dto.wizardTexts;
140	  const genericErrorMessage = trimmedString(
141	    isRecord(wizardRaw) ? wizardRaw['genericErrorMessage'] : null,
142	  );
143	  if (genericErrorMessage === null) {
144	    throw contractError(`missing genericErrorMessage for ${requestedCode}`);
145	  }
146	
147	  const summaryRaw = dto.summaryStepTexts;
148	  const texts: UiTexts = {
149	    wizard: mapTextGroup(wizardRaw, WIZARD_TEXT_KEYS),
150	    formStep: mapTextGroup(dto.formStepTexts, FORM_STEP_TEXT_KEYS),
151	    plansStep: mapTextGroup(dto.plansStepTexts, PLANS_STEP_TEXT_KEYS),
152	    summaryStep: {
153	      page: mapTextGroup(summaryRaw, SUMMARY_STEP_TEXT_SECTIONS.page),
154	      data: mapTextGroup(summaryRaw, SUMMARY_STEP_TEXT_SECTIONS.data),
155	      plan: mapTextGroup(summaryRaw, SUMMARY_STEP_TEXT_SECTIONS.plan),
156	      terms: mapTextGroup(summaryRaw, SUMMARY_STEP_TEXT_SECTIONS.terms),
157	      payment: mapTextGroup(summaryRaw, SUMMARY_STEP_TEXT_SECTIONS.payment),
158	    },
159	    confirmation: mapTextGroup(dto.confirmationTexts, CONFIRMATION_TEXT_KEYS),
160	  };
161	
162	  return {
163	    status: 'ready',
164	    country: { code: requestedCode, name, intlLocale, currency, minimumAge },
165	    genericErrorMessage,
166	    texts,
167	  };
168	}
169	
170	/**
171	 * Warnings for missing texts: attribute names only (no user data). The configuration is still
172	 * usable; the affected screen shows the generic error message.
173	 */
174	export function missingTextWarnings(texts: UiTexts): string[] {
175	  const groups: [string, TextGroup<string>][] = [
176	    ['wizardTexts', texts.wizard],
177	    ['formStepTexts', texts.formStep],
178	    ['plansStepTexts', texts.plansStep],
179	    ['summaryStepTexts.page', texts.summaryStep.page],
180	    ['summaryStepTexts.data', texts.summaryStep.data],
181	    ['summaryStepTexts.plan', texts.summaryStep.plan],
182	    ['summaryStepTexts.terms', texts.summaryStep.terms],
183	    ['summaryStepTexts.payment', texts.summaryStep.payment],
184	    ['confirmationTexts', texts.confirmation],
185	  ];
186	  const warnings: string[] = [];
187	  for (const [name, group] of groups) {
188	    if (group.status === 'configError') {
189	      warnings.push(`[cms] missing texts in ${name}: ${group.missing.join(', ')}`);
190	    }
191	  }
192	  return warnings;
193	}
194	
195	/**
196	 * Combines C3 and C4 into the country configuration (api-contracts "Estado de FormConfig").
197	 * Precedence: a missing step 1 text (form step or wizard texts: legends and indicator) →
198	 * `configError` (REQ-01.13); then `empty` (REQ-01.5); then `unavailable` (REQ-01.22).
199	 */
200	export function assembleCountryConfig(
201	  countryData: Extract<CountryDataMapping, { status: 'ready' }>,
202	  formFields: FormFieldsMapping,
203	): CountryConfig {
204	  const textsMissing =
205	    countryData.texts.formStep.status === 'configError' ||
206	    countryData.texts.wizard.status === 'configError';
207	  const status: FormStatus = textsMissing ? 'configError' : formFields.status;
208	  const form: FormConfig = { status, fields: formFields.fields };
209	  return {
210	    country: countryData.country,
211	    genericErrorMessage: countryData.genericErrorMessage,
212	    texts: countryData.texts,
213	    form,
214	  };
215	}
216	
217	function isSupportedByIntl(intlLocale: string, currency: string): boolean {
218	  try {
219	    new Intl.NumberFormat(intlLocale, { style: 'currency', currency });
220	    return true;
221	  } catch {
222	    return false;
223	  }
224	}
