1	import { CountryConfig, TextGroup } from '../../core/country/country-config';
2	
3	/** Screens under `/:country` (ADR-0001). The confirmation is not a step (D7). */
4	export type WizardScreen = 'form' | 'plans' | 'summary' | 'confirmation';
5	export type StepNumber = 1 | 2 | 3;
6	
7	const STEP_BY_SCREEN: Readonly<Record<WizardScreen, StepNumber | null>> = {
8	  form: 1,
9	  plans: 2,
10	  summary: 3,
11	  confirmation: null,
12	};
13	
14	export function isWizardScreen(value: unknown): value is WizardScreen {
15	  return typeof value === 'string' && value in STEP_BY_SCREEN;
16	}
17	
18	/** Step number shown in the indicator, or `null` for the confirmation. */
19	export function stepOf(screen: WizardScreen): StepNumber | null {
20	  return STEP_BY_SCREEN[screen];
21	}
22	
23	/** What the main heading of a screen shows: its Strapi title, or the generic error (G2-2). */
24	export type ScreenHeading =
25	  | { readonly kind: 'title'; readonly text: string }
26	  | { readonly kind: 'configError'; readonly text: string };
27	
28	/**
29	 * Heading of a screen from the country texts. A missing title is a configuration error: the
30	 * screen shows the generic error message of the country, never a default text (REQ-01.13).
31	 */
32	export function screenHeading(config: CountryConfig, screen: WizardScreen): ScreenHeading {
33	  const title = screenTitle(config, screen);
34	  return title === null
35	    ? { kind: 'configError', text: config.genericErrorMessage }
36	    : { kind: 'title', text: title };
37	}
38	
39	function screenTitle(config: CountryConfig, screen: WizardScreen): string | null {
40	  switch (screen) {
41	    case 'form':
42	      return titleOf(config.texts.formStep);
43	    case 'plans':
44	      return titleOf(config.texts.plansStep);
45	    case 'summary':
46	      return titleOf(config.texts.summaryStep.page);
47	    case 'confirmation':
48	      return titleOf(config.texts.confirmation);
49	  }
50	}
51	
52	/** The title of a group is only usable when the whole group is complete (G2-2). */
53	function titleOf<K extends string>(group: TextGroup<K | 'title'>): string | null {
54	  return group.status === 'ok' ? group.texts.title : null;
55	}
