1	/*
2	 * Global styles (D12, extended by D13): visual style inspired by the SURA site.
3	 * Palette, shapes, spacing and motion live in custom properties; components reuse them.
4	 * Contrast (WCAG AA) of each text/background pair is noted next to the token.
5	 * Font: Figtree (OFL), self-hosted through `@fontsource-variable/figtree` (angular.json `styles`),
6	 * so the CSP `default-src 'self'` does not change (D13).
7	 * No horizontal scroll from 320 px (REQ-01.33, REQ-02.29, REQ-03.36).
8	 */
9	
10	:root {
11	  /* Brand */
12	  --color-primary: #2d6df6; /* 4.54:1 on white; 3.75:1 on surface (large text / UI only) */
13	  --color-primary-dark: #0033a0; /* 10.6:1 on white; 8.76:1 on surface */
14	  --color-accent: #e3e829; /* CTA background */
15	  --color-accent-hover: #d4d91f; /* on-accent on it: 7.17:1 */
16	  --color-accent-active: #c9ce14; /* on-accent on it: 6.43:1 */
17	  --color-on-accent: #26328c; /* 8.26:1 on accent; 10.95:1 on white; 9.05:1 on surface */
18	  --color-surface: #dfeaff; /* hero, selected plan, highlighted blocks */
19	  --color-surface-strong: #ccdcff; /* pressed secondary button: on-accent 7.95:1 */
20	  --color-surface-soft: #f5f8ff;
21	
22	  /* Text and lines */
23	  --color-text: #1c1c24; /* 16.9:1 on white; 13.98:1 on surface */
24	  --color-text-muted: #3f3f41; /* 10.5:1 on white; 8.68:1 on surface */
25	  --color-link: #0b5fff; /* 5.13:1 on white */
26	  --color-border: #e3eaf7; /* decorative card borders */
27	  --color-border-strong: #6b6b70; /* inputs and UI boundaries: 5.3:1 on white, 4.38:1 on surface */
28	  --color-focus: #0033a0; /* focus ring: 10.6:1 on white, 8.76:1 on surface, 8:1 on accent */
29	  --focus-halo: 0 0 0 4px rgb(45 109 246 / 0.22); /* decorative halo, the outline is the indicator */
30	
31	  /* States */
32	  --color-error: #b3261e; /* 6.54:1 on white; 5.92:1 on error surface */
33	  --color-error-surface: #fdf1f0;
34	  --color-disabled-bg: #f2f2f2;
35	  --color-disabled-text: #5c5c61; /* 5.94:1 on disabled background */
36	
37	  /* Shapes, elevation and layout (4/8 px spacing scale) */
38	  --radius-sm: 0.625rem;
39	  --radius-md: 0.5rem;
40	  --radius-lg: 1rem;
41	  --radius-pill: 1.75rem;
42	  --shadow-sm: 0 1px 2px rgb(0 51 160 / 0.06), 0 2px 8px rgb(0 51 160 / 0.08);
43	  --shadow-md: 0 4px 16px rgb(0 51 160 / 0.12);
44	  --container-max: 72rem;
45	  --gutter: 1rem;
46	  --card-padding: 1.25rem;
47	  --font-family: 'Figtree Variable', system-ui, 'Segoe UI', Roboto, sans-serif;
48	
49	  /* Motion */
50	  --ease-out: cubic-bezier(0.2, 0.7, 0.3, 1);
51	  --duration-fast: 150ms;
52	  --duration-view: 220ms;
53	}
