215	/*
216	 * Country links (selection page and "país no disponible"): large white cards. The icon and the
217	 * arrow are empty pseudo-elements, so the accessible name is still only the country name.
218	 */
219	.country-links {
220	  display: grid;
221	  grid-template-columns: repeat(auto-fill, minmax(min(100%, 14rem), 1fr));
222	  gap: 1rem;
