1	/**
2	 * Strapi 5 REST DTOs (api-contracts §2).
3	 *
4	 * Responses are `unknown` at the boundary (CLAUDE.md §8: no `any`) and are narrowed here. A DTO
5	 * type only fixes the attribute *names* documented in the contract; every value stays `unknown`
6	 * until a mapper checks it, so a change in Strapi can never reach the domain unvalidated.
7	 */
8	
9	export type UnknownRecord = Readonly<Record<string, unknown>>;
10	
11	/** Documented attribute names with unchecked values. */
12	export type Dto<K extends string> = { readonly [P in K]?: unknown };
13	
14	export type CountrySummaryDto = Dto<'documentId' | 'code' | 'name'>;
15	export type CountrySelectionDto = Dto<'heading' | 'intro' | 'countryListLabel'>;
16	export type CountryConfigDto = Dto<
17	  | 'documentId'
18	  | 'code'
19	  | 'name'
20	  | 'intlLocale'
21	  | 'currency'
22	  | 'minimumAge'
23	  | 'wizardTexts'
24	  | 'formStepTexts'
25	  | 'plansStepTexts'
26	  | 'summaryStepTexts'
27	  | 'confirmationTexts'
28	>;
29	export type FormFieldDto = Dto<
30	  | 'documentId'
31	  | 'key'
32	  | 'label'
33	  | 'type'
34	  | 'required'
35	  | 'helpText'
36	  | 'errorMessage'
37	  | 'order'
38	  | 'section'
39	  | 'role'
40	  | 'options'
41	  | 'validations'
42	>;
43	export type SelectOptionDto = Dto<'value' | 'label'>;
44	export type ValidationRuleDto = Dto<'kind' | 'value' | 'pattern'>;
45	export type PlanDto = Dto<
46	  | 'documentId'
47	  | 'name'
48	  | 'shortDescription'
49	  | 'basePrice'
50	  | 'currency'
51	  | 'order'
52	  | 'recommended'
53	  | 'active'
54	  | 'coverages'
55	  | 'benefits'
56	>;
57	export type PlanItemDto = Dto<'label'>;
58	export type CountryPriceFactorsDto = Dto<'code' | 'priceFactors'>;
59	export type PriceFactorDto = Dto<'role' | 'operand' | 'min' | 'max' | 'multiplier'>;
60	export type CountryTermsDto = Dto<'code' | 'termsAndConditions'>;
61	export type BlockNodeDto = Dto<
62	  | 'type'
63	  | 'children'
64	  | 'text'
65	  | 'level'
66	  | 'format'
67	  | 'url'
68	  | 'bold'
69	  | 'italic'
70	  | 'underline'
71	  | 'strikethrough'
72	  | 'code'
73	>;
74	
75	export function isRecord(value: unknown): value is UnknownRecord {
76	  return typeof value === 'object' && value !== null && !Array.isArray(value);
77	}
78	
79	/** Narrows an unknown value to a DTO with the given attribute names, or `null`. */
80	export function asDto<K extends string>(value: unknown): Dto<K> | null {
81	  // Safe: every attribute of `Dto<K>` is optional and `unknown`, so any object fits.
82	  return isRecord(value) ? (value as Dto<K>) : null;
83	}
84	
85	/** Trimmed non-empty string, or `null` (empty, blank or not a string). */
86	export function trimmedString(value: unknown): string | null {
87	  if (typeof value !== 'string') {
88	    return null;
89	  }
90	  const trimmed = value.trim();
91	  return trimmed === '' ? null : trimmed;
92	}
93	
94	/** Finite number from a JSON number or a numeric string (Strapi `decimal`, ADR-0005), or `null`. */
95	export function numeric(value: unknown): number | null {
96	  if (typeof value === 'number') {
97	    return Number.isFinite(value) ? value : null;
98	  }
99	  if (typeof value === 'string' && value.trim() !== '') {
100	    const parsed = Number(value);
101	    return Number.isFinite(parsed) ? parsed : null;
102	  }
103	  return null;
104	}
105	
106	/** Integer or `null`; anything else (decimal, string, NaN) is `undefined` = malformed. */
107	export function integerOrNull(value: unknown): number | null | undefined {
108	  if (value === null || value === undefined) {
109	    return null;
110	  }
111	  return typeof value === 'number' && Number.isInteger(value) ? value : undefined;
112	}
113	
114	/** `null`/absent → `[]`; an array → itself; anything else → `null` (malformed). */
115	export function arrayOrEmpty(value: unknown): readonly unknown[] | null {
116	  if (value === null || value === undefined) {
117	    return [];
118	  }
119	  return Array.isArray(value) ? value : null;
120	}
121	
122	export function isOneOf<T extends string>(value: unknown, catalog: readonly T[]): value is T {
123	  return typeof value === 'string' && (catalog as readonly string[]).includes(value);
124	}
125

