1	import { Injectable } from '@angular/core';
2	import { ActivatedRouteSnapshot, BaseRouteReuseStrategy } from '@angular/router';
3	import { countryCodeOf } from './country-route';
4	
5	/**
6	 * Never reuses a route component across countries (REQ-01.25, REQ-03.37).
7	 *
8	 * The default strategy reuses a component when only the params change, so going from `/cl/form`
9	 * to `/co/form` kept the shell, its `CountryContext` and the step 1 form created for Chile (the
10	 * form is built once in `ngOnInit`, ADR-0002). With this strategy everything under `/:country` is
11	 * created again for the new country. Within one country, routes are reused as usual.
12	 */
13	@Injectable()
14	export class CountryRouteReuseStrategy extends BaseRouteReuseStrategy {
15	  override shouldReuseRoute(
16	    future: ActivatedRouteSnapshot,
17	    current: ActivatedRouteSnapshot,
18	  ): boolean {
19	    return (
20	      super.shouldReuseRoute(future, current) && countryCodeOf(future) === countryCodeOf(current)
21	    );
22	  }
23	}
