// Throwaway visual check (not part of the repo): screenshots + horizontal scroll + target sizes.
const { chromium } = require(process.argv[2]);
const out = process.argv[3];
const base = 'http://localhost:4300';

async function metrics(page, name) {
  const m = await page.evaluate(() => {
    const small = [];
    document.querySelectorAll('button, input[type="checkbox"], input[type="radio"]').forEach((el) => {
      const r = el.getBoundingClientRect();
      if (r.width === 0 && r.height === 0) return;
      if (r.width < 24 || r.height < 24) small.push(`${el.tagName}#${el.id} ${r.width}x${r.height}`);
      if (el.tagName === 'BUTTON' && r.height < 44) small.push(`button<44 ${el.textContent.trim()} ${r.height}`);
    });
    return {
      sw: document.documentElement.scrollWidth,
      cw: document.documentElement.clientWidth,
      small,
    };
  });
  console.log(name, JSON.stringify(m));
}

(async () => {
  const browser = await chromium.launch({ channel: 'chrome' });
  for (const width of [320, 1280]) {
    const page = await browser.newPage({ viewport: { width, height: 900 } });
    const shot = async (n) => {
      await metrics(page, `${n}@${width}`);
      await page.screenshot({ path: `${out}/${n}-${width}.png`, fullPage: true });
    };
    await page.goto(base + '/');
    await page.getByRole('link').first().waitFor();
    await shot('01-countries');
    await page.goto(base + '/pe');
    await page.getByRole('link').first().waitFor();
    await shot('02-not-available');
    await page.goto(base + '/co/form');
    await page.getByLabel('Placa').waitFor();
    await page.getByRole('button', { name: 'Continuar' }).click();
    await shot('03-form-errors');
    await page.getByLabel('Tipo de documento').selectOption('cc');
    await page.getByLabel('Número de documento').fill('1234567890');
    await page.getByLabel('Fecha de nacimiento').fill('2000-05-10');
    await page.getByLabel('Ciudad').selectOption('bogota');
    await page.getByLabel('Autorizo el tratamiento de mis datos personales').check();
    await page.getByLabel('Placa').fill('ABC123');
    await page.getByLabel('Marca').selectOption('make_a');
    await page.getByLabel('Año del vehículo').fill('2018');
    await page.getByRole('button', { name: 'Continuar' }).click();
    await page.getByRole('radio').first().waitFor();
    await page.getByRole('radio').nth(1).check();
    await shot('04-plans');
    await page.getByRole('button', { name: 'Continuar' }).click();
    await page.locator('.terms-region').waitFor();
    await shot('05-summary');
    await page.getByRole('checkbox').check();
    await page.keyboard.press('Tab');
    await shot('06-summary-ready');
    await page.getByRole('radio', { name: /rechaz/i }).check().catch(() => {});
    await page.locator('.pay').click();
    await page.waitForTimeout(2500);
    await shot('07-rejected');
    await page.getByRole('radio').first().check();
    await page.locator('.pay').click();
    await page.waitForURL(/confirmation/, { timeout: 10000 });
    await shot('08-confirmation');
    await page.close();
  }
  await browser.close();
})().catch((e) => {
  console.error(e);
  process.exit(1);
});

1	import { CmsQuery } from '../cms-queries';
2	
3	/** One call received by the fake client. */
4	export interface CmsCall {
5	  readonly method: 'findAll' | 'findFirstPage' | 'findSingle';
6	  readonly path: string;
7	  readonly query: CmsQuery;
8	}
9	
10	export type CmsHandler = (call: CmsCall) => Promise<unknown>;
11	
12	export type CmsRequestId = 'C1' | 'C2' | 'C3' | 'C4' | 'C5' | 'C6' | 'C7';
13	
14	/** Which request of api-contracts §2 a call is. */
15	export function requestIdOf(call: CmsCall): CmsRequestId {
16	  switch (call.path) {
17	    case 'country-selection':
18	      return 'C2';
19	    case 'form-fields':
20	      return 'C4';
21	    case 'plans':
22	      return 'C5';
23	  }
24	  if (call.query['populate[0]'] === 'wizardTexts') {
25	    return 'C3';
26	  }
27	  if (call.query['populate[0]'] === 'priceFactors') {
28	    return 'C6';
29	  }
30	  return call.query['fields[1]'] === 'termsAndConditions' ? 'C7' : 'C1';
31	}
32	
33	/** Country code of a filtered call (`filters[code]` or `filters[country][code]`). */
34	export function countryOf(call: CmsCall): string | undefined {
35	  return call.query['filters[code][$eq]'] ?? call.query['filters[country][code][$eq]'];
36	}
37	
38	/** A promise that never settles: the request stays "loading". */
39	export const pending = (): Promise<never> => new Promise<never>(() => undefined);
40	
41	/**
42	 * Fake `CmsClient` for component tests (ADR-0007). Records every call and answers with the
43	 * handler set by the test. Provide it with `{ provide: CmsClient, useValue: fake }`. Test-only.
44	 */
45	export class FakeCmsClient {
46	  readonly calls: CmsCall[] = [];
47	  handler: CmsHandler = () => pending();
48	
49	  findAll(path: string, query: CmsQuery): Promise<unknown> {
50	    return this.dispatch({ method: 'findAll', path, query });
51	  }
52	
53	  findFirstPage(path: string, query: CmsQuery): Promise<unknown> {
54	    return this.dispatch({ method: 'findFirstPage', path, query });
55	  }
56	
57	  findSingle(path: string, query: CmsQuery): Promise<unknown> {
58	    return this.dispatch({ method: 'findSingle', path, query });
59	  }
60	
61	  callsTo(path: string): CmsCall[] {
62	    return this.calls.filter((call) => call.path === path);
63	  }
64	
65	  private dispatch(call: CmsCall): Promise<unknown> {
66	    this.calls.push(call);
67	    return this.handler(call);
68	  }
69	}
