// Throwaway visual check for D14 (not part of the repo).
// argv: <playwright path> <out dir>
const { chromium } = require(process.argv[2]);
const out = process.argv[3];
const base = 'http://localhost:4300';
const LABELS = { co: 'Cambiar de país', cl: 'Cambiar de país' };

async function addLabelIfMissing(page) {
  await page.route('**/api/countries?*', async (route) => {
    const url = decodeURIComponent(route.request().url());
    if (!url.includes('populate[0]=wizardTexts')) return route.continue();
    const res = await route.fetch();
    const body = await res.json();
    let patched = false;
    for (const c of body.data ?? []) {
      if (c.wizardTexts && !c.wizardTexts.changeCountryLabel) {
        c.wizardTexts.changeCountryLabel = LABELS[c.code];
        patched = true;
      }
    }
    if (patched) console.log('  (intercepted C3: changeCountryLabel added, not yet in Strapi)');
    await route.fulfill({ response: res, json: body });
  });
}

async function metrics(page, name) {
  const m = await page.evaluate(() => {
    const link = Array.from(document.querySelectorAll('a')).find((a) => a.getAttribute('href') === '/');
    const r = link?.getBoundingClientRect();
    return {
      sw: document.documentElement.scrollWidth,
      cw: document.documentElement.clientWidth,
      link: link ? { text: link.textContent.trim(), w: Math.round(r.width), h: Math.round(r.height), color: getComputedStyle(link).color } : null,
    };
  });
  console.log(name, JSON.stringify(m));
}

(async () => {
  const browser = await chromium.launch({ channel: 'chrome' });
  for (const width of [375, 1280]) {
    const page = await browser.newPage({ viewport: { width, height: 900 } });
    await addLabelIfMissing(page);
    const shot = async (n, full = true) => {
      await metrics(page, `${n}@${width}`);
      await page.screenshot({ path: `${out}/${n}-${width}.png`, fullPage: full });
    };
    await page.goto(base + '/co/form');
    await page.getByLabel('Placa').waitFor();
    await shot('01-form-link', false);
    // Focus ring of the link (keyboard): Tab from the top of the document.
    await page.getByRole('link', { name: 'Cambiar de país' }).focus();
    await page.keyboard.press('Shift+Tab');
    await page.keyboard.press('Tab');
    const focused = await page.evaluate(() => document.activeElement?.textContent?.trim());
    console.log(`focused after Tab@${width}:`, focused);
    await page.screenshot({ path: `${out}/02-link-focus-${width}.png`, clip: { x: 0, y: 0, width, height: 260 } });

    await page.getByLabel('Tipo de documento').selectOption('cc');
    await page.getByLabel('Número de documento').fill('1234567890');
    await page.getByLabel('Fecha de nacimiento').fill('2000-05-10');
    await page.getByLabel('Ciudad').selectOption('bogota');
    await page.getByLabel('Autorizo el tratamiento de mis datos personales').check();
    await page.getByLabel('Placa').fill('ABC123');
    await page.getByLabel('Marca').selectOption('make_a');
    await page.getByLabel('Año del vehículo').fill('2018');

    // Change country and come back: data must still be there (D6).
    await page.getByRole('link', { name: 'Cambiar de país' }).click();
    await page.waitForURL(base + '/');
    await page.getByRole('link', { name: 'Colombia' }).waitFor();
    await shot('03-back-to-countries');
    await page.getByRole('link', { name: 'Colombia' }).click();
    await page.getByLabel('Placa').waitFor();
    const restored = {
      doc: await page.getByLabel('Número de documento').inputValue(),
      plate: await page.getByLabel('Placa').inputValue(),
      year: await page.getByLabel('Año del vehículo').inputValue(),
    };
    console.log(`restored@${width}:`, JSON.stringify(restored));

    await page.getByRole('button', { name: 'Continuar' }).click();
    await page.getByRole('radio').first().waitFor();
    // Click on a coverage item of the last plan (not on the label nor the radio).
    const cards = page.locator('.plan');
    const last = cards.last();
    const name = (await last.locator('.plan-name').textContent()).trim();
    const item = last.locator('ul li').first();
    await item.click();
    const checked = await last.locator('input[type="radio"]').isChecked();
    console.log(`plans@${width}: clicked coverage of "${name}" -> checked=${checked}`);
    // Click on the description of the first plan.
    await cards.first().locator('.plan-description').click();
    console.log(`plans@${width}: clicked description of first -> checked=${await cards.first().locator('input[type="radio"]').isChecked()}`);
    await item.click();
    await shot('04-plans-after-coverage-click');

    await page.getByRole('button', { name: 'Continuar' }).click();
    await page.locator('.terms-region').waitFor();
    await shot('05-summary', false);
    await page.close();
  }
  await browser.close();
})().catch((e) => {
  console.error(e);
  process.exit(1);
});

